def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # Arrays to store the maximum sum of increasing subsequence ending at each index
    inc = arr[:]
    # Arrays to store the maximum sum of decreasing subsequence starting at each index
    dec = arr[:]

    # Compute maximum sum of increasing subsequence ending at each index
    for i in range(n):
        for j in range(i):
            if arr[j] < arr[i] and inc[j] + arr[i] > inc[i]:
                inc[i] = inc[j] + arr[i]

    # Compute maximum sum of decreasing subsequence starting at each index
    for i in range(n - 2, -1, -1):
        for j in range(n - 1, i, -1):
            if arr[j] < arr[i] and dec[j] + arr[i] > dec[i]:
                dec[i] = dec[j] + arr[i]

    # Find the maximum sum of bitonic subsequence
    max_sum_bitonic = 0
    for i in range(n):
        # Subtract arr[i] once because it's counted twice in inc and dec
        current_sum = inc[i] + dec[i] - arr[i]
        if current_sum > max_sum_bitonic:
            max_sum_bitonic = current_sum

    return max_sum_bitonic

