def newman_prime(n):
    def nsw_sequence(limit):
        # Generate NSW numbers up to a certain limit
        # NSW numbers: a(0)=1, a(1)=1, a(n)=2*a(n-1)+a(n-2)
        a, b = 1, 1
        seq = [a, b]
        while len(seq) < limit:
            a, b = b, 2*b + a
            seq.append(b)
        return seq

    def is_prime(x):
        if x < 2:
            return False
        if x in (2, 3):
            return True
        if x % 2 == 0 or x % 3 == 0:
            return False
        i = 5
        while i * i <= x:
            if x % i == 0 or x % (i + 2) == 0:
                return False
            i += 6
        return True

    # NSW primes are NSW numbers that are prime
    # We don't know how many to generate, so generate until we find n primes
    primes = []
    i = 0
    a, b = 1, 1
    while len(primes) < n:
        if is_prime(a):
            primes.append(a)
        a, b = b, 2*b + a
        i += 1
    return primes[-1]
