def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # max sum of increasing subsequence ending at i
    inc = arr[:]
    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i] and inc[j] + arr[i] > inc[i]:
                inc[i] = inc[j] + arr[i]

    # max sum of decreasing subsequence starting at i
    dec = arr[:]
    for i in range(n-2, -1, -1):
        for j in range(n-1, i, -1):
            if arr[j] < arr[i] and dec[j] + arr[i] > dec[i]:
                dec[i] = dec[j] + arr[i]

    max_bitonic = 0
    for i in range(n):
        # subtract arr[i] because it is counted twice in inc[i] + dec[i]
        max_bitonic = max(max_bitonic, inc[i] + dec[i] - arr[i])

    return max_bitonic
